-- Canonical text only. Permissions are resolved from live grants on every search.
CREATE TABLE search_text (key TEXT NOT NULL, variant TEXT NOT NULL, workspace_id TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL, page_id TEXT, title TEXT NOT NULL, text TEXT NOT NULL, title_fold TEXT NOT NULL, text_fold TEXT NOT NULL, document_json TEXT NOT NULL, container_id TEXT, status TEXT, lifecycle TEXT, archived_at TEXT, trashed_at TEXT, author_id TEXT, updated_at TEXT NOT NULL, contributors_json TEXT NOT NULL, PRIMARY KEY(key,variant));
CREATE INDEX pages_search_parent ON pages(workspace_id,parent_page_id) WHERE parent_page_id IS NOT NULL;
CREATE INDEX search_text_workspace ON search_text(workspace_id,kind);
CREATE TABLE search_dirty (key TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, generation TEXT NOT NULL);
CREATE INDEX search_dirty_workspace ON search_dirty(workspace_id);
ALTER TABLE discovery_snapshots ADD COLUMN search_summary_json TEXT;
CREATE TRIGGER search_pages_insert AFTER INSERT ON pages BEGIN INSERT INTO search_dirty(key,workspace_id,generation) VALUES(CASE WHEN NEW.page_kind='record' THEN 'record:' ELSE 'page:' END||NEW.id,NEW.workspace_id,hex(randomblob(16))) ON CONFLICT(key) DO UPDATE SET generation=excluded.generation; END;
CREATE TRIGGER search_pages_update AFTER UPDATE ON pages BEGIN INSERT INTO search_dirty(key,workspace_id,generation) VALUES(CASE WHEN OLD.page_kind='record' THEN 'record:' ELSE 'page:' END||OLD.id,OLD.workspace_id,hex(randomblob(16))) ON CONFLICT(key) DO UPDATE SET generation=excluded.generation; INSERT INTO search_dirty(key,workspace_id,generation) VALUES(CASE WHEN NEW.page_kind='record' THEN 'record:' ELSE 'page:' END||NEW.id,NEW.workspace_id,hex(randomblob(16))) ON CONFLICT(key) DO UPDATE SET generation=excluded.generation; END;
CREATE TRIGGER search_pages_delete AFTER DELETE ON pages BEGIN INSERT INTO search_dirty(key,workspace_id,generation) VALUES(CASE WHEN OLD.page_kind='record' THEN 'record:' ELSE 'page:' END||OLD.id,OLD.workspace_id,hex(randomblob(16))) ON CONFLICT(key) DO UPDATE SET generation=excluded.generation; END;
